tool_use_result.originalFile:
import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate, addDays } from './dates.js';

/**
 * Create an invoice with line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  const resolvedTerms = terms ?? 'NET30';
  const dueDate = calculateDueDate(issueDate, resolvedTerms);
  if (!dueDate) return fail('TERMS_INVALID');

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
    if (!isValidDiscount(discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    terms: resolvedTerms,
    dueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total price for a line item (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount for a line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discountPercent = line.discountPercent ?? 0;
  return Math.max(0, Math.round(total * discountPercent / 100));
}

/**
 * Calculate the VAT amount for a line item (VAT on amount after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }} line
 * @returns {number}
 */
export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = total - discount;
  const vatRate = line.vatRate ?? 0;
  return Math.max(0, roundCents(amountAfterDiscount * vatRate / 100));
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
  return {
    subtotal: Math.max(0, subtotal),
    discount: Math.max(0, discount),
    vat: Math.max(0, vat),
    total: Math.max(0, subtotal - discount + vat),
  };
}

/**
 * Add or increase a line item on a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string, qty: number, name: string, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
  const finalDiscountPercent = discountPercent !== undefined ? discountPercent : tierDiscount;

  if (!isValidDiscount(finalDiscountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex !== -1) {
    newLines[existingLineIndex].qty += qty;
  } else {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: finalDiscountPercent,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line item from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines
    .slice(0, lineIndex)
    .concat(invoice.lines.slice(lineIndex + 1));

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it an invoice number.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - Array of invoice numbers already used
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') {
    return addDays(issueDate, 14);
  } else if (terms === 'NET30') {
    return addDays(issueDate, 30);
  } else if (terms === 'EOM') {
    const year = parseInt(issueDate.slice(0, 4), 10);
    const month = parseInt(issueDate.slice(5, 7), 10);
    const lastDay = new Date(Date.UTC(year, month, 0)).getUTCDate();
    return `${issueDate.slice(0, 7)}-${String(lastDay).padStart(2, '0')}`;
  }
  return null;
}

function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

