  const originalStatus = invoice.status;
  const originalKeys = Object.keys(invoice);

  issueInvoice(invoice, []);

  assert.equal(invoice.status, originalStatus);
  assert.deepEqual(Object.keys(invoice), originalKeys);
  assert(!('number' in invoice));
});

