  assert.equal(result.error, 'QTY_INVALID');
});

test('returns UNKNOWN_SKU for invalid SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'INVALID-SKU', qty: 1 }],
  });

  assert(result.ok === false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('returns UNKNOWN_SKU when one of multiple lines has invalid SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'INVALID-SKU', qty: 2 },
    ],
  });

  assert(result.ok === false);
  assert.equal(result.error, 'UNKNOWN_SKU');
});

test('does not mutate the input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  };
  const originalInput = JSON.parse(JSON.stringify(input));

  createInvoice(input);

  assert.deepEqual(input, originalInput);
});

test('returns a new lines array, not a reference to input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  };

  const result = createInvoice(input);

  assert(result.ok === true);
  assert(result.value.lines !== input.lines);
});

test('handles all catalogue products', () => {
  const skus = [
    'DES-HOUR',
    'DEV-HOUR',
    'COPY-HOUR',
    'SUPPORT-HOUR',
    'LOGO-PACK',
    'BRAND-BOOK',
    'ICON-SET',
    'PHOTO-LIC',
    'FONT-LIC',
    'STICKER',
    'HOST-MONTH',
    'DOMAIN-YEAR',
    'PRINT-A4',
    'PRINT-A3',
    'BOOK-DESIGN',
    'MAGAZINE',
    'WORKSHOP-DAY',
    'TALK',
  ];

  for (const sku of skus) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku, qty: 1 }],
    });
    assert(result.ok === true, `Failed for SKU: ${sku}`);
  }
});

test('lineTotal calculates qty × unitPrice', () => {
  const line = { qty: 5, unitPrice: 9500 };
  assert.equal(lineTotal(line), 47500);
});

test('lineTotal returns 0 for qty 0', () => {
  const line = { qty: 0, unitPrice: 9500 };
  assert.equal(lineTotal(line), 0);
});

test('lineTotal works with different prices', () => {
  const testCases = [
    { qty: 1, unitPrice: 50, expected: 50 },
    { qty: 10, unitPrice: 8500, expected: 85000 },
    { qty: 2, unitPrice: 120000, expected: 240000 },
    { qty: 100, unitPrice: 37, expected: 3700 },
  ];

  for (const { qty, unitPrice, expected } of testCases) {
    assert.equal(lineTotal({ qty, unitPrice }), expected);
  }
});

test('invoiceTotals calculates subtotal for single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500 }],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 47500,
    discount: 0,
    vat: 0,
    total: 47500,
  });
});

test('invoiceTotals sums multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500 },
      { qty: 2, unitPrice: 8500 },
      { qty: 1, unitPrice: 60000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 47500 + 17000 + 60000,
    discount: 0,
    vat: 0,
    total: 47500 + 17000 + 60000,
  });
});

test('invoiceTotals works with empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 0,
    discount: 0,
    vat: 0,
    total: 0,
  });
});

test('invoiceTotals with invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });

  assert(result.ok === true);
  const totals = invoiceTotals(result.value);
  const subtotal = 5 * 9500 + 2 * 8500;
  const discount = Math.round(subtotal * 5 / 100);
  const devHourAfterDiscount = 5 * 9500 - Math.round(5 * 9500 * 5 / 100);
  const desHourAfterDiscount = 2 * 8500 - Math.round(2 * 8500 * 5 / 100);
  const vat = roundCents(devHourAfterDiscount * 21 / 100) + roundCents(desHourAfterDiscount * 21 / 100);
  assert.deepEqual(totals, {
    subtotal,
    discount,
    vat,
    total: subtotal - discount + vat,
  });
});

test('invoiceTotals with various product prices', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'STICKER', qty: 100 },
      { sku: 'ICON-SET', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert(result.ok === true);
  const totals = invoiceTotals(result.value);
  const subtotal = 100 * 50 + 10 * 980 + 1 * 120000;
