test('returns DATE_INVALID for invalid date format', () => {
  const testCases = [
    '2026-10-7',
    '26-10-07',
    '2026/10/07',
    '2026.10.07',
    '10-07-2026',
    '2026-13-01',
    '2026-10',
    '10/07/2026',
    '',
  ];

  for (const date of testCases) {
    const result = createInvoice({
