test('applyVoucher rejects fractional amount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok === true);
  const invoice = result.value;

  const voucherResult = applyVoucher(invoice, { code: 'SAVE10', amount: 10000.5 });

  assert(voucherResult.ok === false);
  assert.equal(voucherResult.error, 'AMOUNT_INVALID');
});

test('applyVoucher rejects duplicate voucher', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok === true);
  let invoice = result.value;

  const voucherResult1 = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert(voucherResult1.ok === true);
  invoice = voucherResult1.value;

  const voucherResult2 = applyVoucher(invoice, { code: 'SAVE20', amount: 20000 });

  assert(voucherResult2.ok === false);
  assert.equal(voucherResult2.error, 'VOUCHER_EXISTS');
});

test('applyVoucher returns NOT_DRAFT for issued invoices', () => {
  const issueResult = issueInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
  }, []);

  assert(issueResult.ok === true);
  const invoice = issueResult.value;

  const voucherResult = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });

  assert(voucherResult.ok === false);
  assert.equal(voucherResult.error, 'NOT_DRAFT');
});

test('invoiceTotals includes voucher field', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok === true);
  const invoice = result.value;
  const totals = invoiceTotals(invoice);

  assert('voucher' in totals);
  assert.equal(totals.voucher, 0);
});

test('invoiceTotals subtracts voucher from total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok === true);
  let invoice = result.value;
  const totalsWithoutVoucher = invoiceTotals(invoice);

  const voucherResult = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert(voucherResult.ok === true);
  invoice = voucherResult.value;

  const totalsWithVoucher = invoiceTotals(invoice);

  assert.equal(totalsWithVoucher.voucher, 10000);
  assert.equal(totalsWithVoucher.total, totalsWithoutVoucher.total - 10000);
});

test('invoiceTotals with large voucher clamps to zero', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok === true);
  let invoice = result.value;

  const voucherResult = applyVoucher(invoice, { code: 'HUGE', amount: 9999999 });
  assert(voucherResult.ok === true);
  invoice = voucherResult.value;

  const totals = invoiceTotals(invoice);

  assert(totals.total >= 0);
});

test('applyVoucher with small voucher amount', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok === true);
  const invoice = result.value;

  const voucherResult = applyVoucher(invoice, { code: 'PENNY', amount: 1 });

  assert(voucherResult.ok === true);
  assert.equal(voucherResult.value.voucher.amount, 1);
});

