test('lineVAT rounds correctly', () => {
  const line = { qty: 3, unitPrice: 1000, discountPercent: 0, vatRate: 21 };
  const vat = lineVAT(line);
  assert.equal(vat, 630);
});

test('invoiceTotals includes VAT', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 10000,
    discount: 0,
    vat: 2100,
    total: 12100,
  });
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 10000, discountPercent: 10, vatRate: 21 }],
  };

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 10000,
    discount: 1000,
    vat: 1890,
    total: 10890,
  });
});

test('invoiceTotals sums VAT across multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 9 },
      { qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);

